<script>
document.getElementById('swapFrom').innerHTML='<option value="NGN">NGN · Nigerian Naira</option><option value="USDT">USDT · Tether</option><option value="USDC">USDC · USD Coin</option><option value="BTC">BTC · Bitcoin</option><option value="ETH">ETH · Ethereum</option><option value="SOL">SOL · Solana</option>';
document.getElementById('swapTo').innerHTML='<option value="NGN">NGN · Nigerian Naira</option><option value="USDT">USDT · Tether</option><option value="USDC">USDC · USD Coin</option><option value="BTC">BTC · Bitcoin</option><option value="ETH">ETH · Ethereum</option><option value="SOL">SOL · Solana</option>';
  const rates={USDT:{NGN:1620},BTC:{NGN:106920000},ETH:{NGN:5800000},NGN:{USDT:1/1620,BTC:1/106920000,ETH:1/5800000}};
  const from=document.getElementById('swapFrom'),to=document.getElementById('swapTo'),amount=document.getElementById('swapAmount');
  function updateSwap(){const rate=rates[from.value]?.[to.value]||1,value=Number(amount.value||0),receive=value*rate,decimals=to.value==='NGN'?2:6;document.getElementById('swapReceive').textContent=`${receive.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:decimals})} ${to.value}`;document.getElementById('swapRate').textContent=`1 ${from.value} = ${rate.toLocaleString(undefined,{maximumFractionDigits:6})} ${to.value}`;document.getElementById('swapFee').textContent=`${(value*.005).toLocaleString(undefined,{maximumFractionDigits:6})} ${from.value}`;}
  [from,to,amount].forEach(field=>field.addEventListener('input',updateSwap));
  document.getElementById('flipSwap').addEventListener('click',()=>{const current=from.value;from.value=to.value;to.value=current;updateSwap();});
  document.getElementById('confirmSwap').addEventListener('click',()=>{if(!Number(amount.value)){alert('Enter an amount to swap.');return;}document.getElementById('swapForm').classList.add('hidden');document.getElementById('swapSuccessText').textContent=`Your ${amount.value} ${from.value} to ${to.value} swap is being processed at the displayed rate.`;document.getElementById('swapSuccess').classList.remove('hidden');lucide.createIcons();});updateSwap();
</script>
<script>
document.getElementById('confirmSwap').addEventListener('click',async function(e){e.preventDefault();e.stopImmediatePropagation();const f=document.getElementById('swapFrom').value,t=document.getElementById('swapTo').value,a=Number(document.getElementById('swapAmount').value),rate=rates[f]?.[t]||0;if(!a||f===t||!rate){alert('Enter a valid amount and an available pair.');return}try{const r=await fetch('../api/financial/action.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'swap',from_currency:f,to_currency:t,amount:a,rate})}),d=await r.json();if(!r.ok||!d.success)throw new Error(d.error||'Swap failed');document.getElementById('swapForm').classList.add('hidden');document.getElementById('swapSuccessText').textContent=`Swap ${d.reference} completed. You received ${Number(d.to_amount).toLocaleString()} ${t}.`;document.getElementById('swapSuccess').classList.remove('hidden');lucide.createIcons()}catch(err){alert(err.message)}},true);
</script>
